from h import *
R(9349945,"بيستو الفستق",
"بيستو الفستق اللذيذ المالح الذي يصعب التوقف عنه، وجاهز في وقت قصير بأربعة مكونات فقط!",
"8 حصص","حصة واحدة",
["1 كوب فستق مقشّر","2 كوب ريحان طازج مكبوس برفق","2 ملعقة كبيرة عصير ليمون أخضر، أي حوالي ليمونة خضراء متوسطة","2 فص ثوم","2-4 ملاعق كبيرة ماء عند الحاجة","ملح + فلفل حسب الرغبة"],
["ضع الفستق والريحان وعصير الليمون الأخضر والثوم في وعاء محضّر الطعام واخلطها حتى تمتزج وتصبح ناعمة في معظمها. ثم تذوّق للتأكد من الملح والفلفل وعدّل حسب الحاجة وأضف الماء عند الحاجة لتخفيف الصلصة.","قدّمه كغموس مع الخضار أو الكروستيني أو البسكويت المالح و/أو أصابع الخبز. أو استخدمه كصلصة مع المعكرونة أو معكرونة الخضار."],
["استخدم محضّر الطعام للحصول على قوام مفروم ناعمًا.","للحصول على قوام أنعم استخدم الخلاط.","اختر أي أعشاب طازجة تفضلها، مع الحفاظ على النسبة نفسها.","يمكن مضاعفة هذه الوصفة بسهولة مرتين أو ثلاث مرات أو أكثر. وهذا مفيد بشكل خاص في موسم الحصاد عندما يكون لديك الكثير من الأعشاب الطازجة في الحديقة لاستهلاكها.","إذا كنت ستستخدم البيستو مع المعكرونة، فأضف رشة كبيرة من الملح إلى ماء المعكرونة للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة."])
R(9350784,"شوربة جالابينو بوبر النباتية",
"تجمع شوربة جالابينو بوبر بين صلصة الجبن النباتية والجالابينو للحصول على لقمة حارة ولذيذة! إنها مفيدة ومشبعة ومرضية وجاهزة في 35 دقيقة!",
"6 حصص","حصة واحدة",
["1 ملعقة كبيرة زبدة نباتية أو سمن نباتي (مارجرين)، واستخدم الماء أو المرق لوصفة خالية من الزيت","1 حبة بصل أصفر أو أحمر مقطعة أرباعًا","2 فص ثوم مقشّر","1 حبة فلفل رومي أحمر مقطعة أرباعًا","3-4 فلفل هالبينو مقطع إلى نصفين، مع إزالة البذور لتقليل الحرارة","1 قرنبيطة مفصّلة إلى زهيرات كبيرة","1 كوب ذرة مجمدة أو معلبة","4 أكواب مرق خضار قليل الصوديوم","1½ كوب كاجو نيء","1 كوب مرق خضار قليل الصوديوم","3 ملاعق كبيرة خل التفاح","¼ كوب خميرة غذائية","1 ملعقة كبيرة تاماري أو صلصة الصويا إن لم تكن تتجنب الغلوتين","1 ملعقة صغيرة مسحوق البصل","1 ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة ملح البحر أو حسب الرغبة"],
["ضع البصل والثوم والفلفل الأحمر والهالبينو في محضّر الطعام وقلّب بالنبض حتى تُفرم ناعمًا جدًا.","في قدر كبير، ضع الزبدة النباتية أو السمن النباتي (المارجرين) إن استخدمته وذوّبه على نار متوسطة. (أو استخدم الماء أو المرق إذا كنت تتجنب الزيت.) ثم أضف الخضار المفرومة التي حضّرتها للتو إلى القدر وقلّبها لمدة 5-7 دقائق حتى تلين ويقل حجمها.","في هذه الأثناء، ضع القرنبيط في المحضّر نفسه وقلّب بالنبض حتى يتفتت، دون إفراط في الفرم أو تحويله إلى هريس. أنت تريد بعض القطع الخشنة. اعمل على دفعات إذا لزم الأمر.","أضف القرنبيط المفروم مع المرق والذرة إلى القدر وقلّب جيدًا. أوصله إلى الغليان على نار عالية، ثم اخفض إلى نار متوسطة إلى منخفضة ودعه يغلي على نار هادئة لمدة 15 دقيقة.","بينما تغلي الشوربة على نار هادئة، حضّر صلصة الجبن النباتية. ضع جميع المكونات في خلاط عالي السرعة واخلطها حتى تصبح ناعمة.","أطفئ النار واسكب صلصة الجبن وقلّب جيدًا. تذوّق للتأكد من الملح والفلفل وأضف المزيد عند الحاجة. ثم قدّمها مزينة بشرائح الجالابينو إن رغبت."],
["اضبط درجة الحرارة حسب ذوقك. نحن نحبها حارة جدًا، لكن إذا كنت تريد حرارة أخف، فاستخدم كمية أقل من الجالابينو وأزل البذور للحصول على مستوى أخف من الحرارة. عدّل التتبيل. تبّل دائمًا حسب ذوقك. فمجرد أن الوصفة تتطلب نصف ملعقة صغيرة من الملح لا يعني أنه لا يمكنك التعديل. وإذا أردت نكهة مدخنة أكثر، فزد البابريكا المدخنة أيضًا. لتكون الوصفة خالية من الزيت: احذف الزبدة النباتية أو السمن النباتي (المارجرين) وقلّب باستخدام الماء أو المرق بدلًا منها. لتكون خالية من المكسرات: يمكنك استبدال الكاجو ببذور دوار الشمس بنتائج مماثلة. يمنح الكاجو غنًى أكثر قليلًا، لكن إذا لم تستطع تناول الكاجو، فإن بذور دوار الشمس بديل جيد. لتكون خالية من الذرة: يمكنك ببساطة حذف الذرة أو استبدالها ببعض الجزر المقطع مكعبات لإضافة لون ولمسة من الحلاوة. انقع الكاجو. إذا لم يكن لديك خلاط عالي السرعة مثل فيتامكس أو بلندتك، فانقع الكاجو أولًا. انقعه في ماء شديد السخونة من الغلاية أو من على الموقد لمدة 30 دقيقة. ثم صفّه واستخدمه. فنقع الكاجو يجعله يلين ويسمح للخلاط الأقل قوة بمعالجته. لا تُفرط في فرم القرنبيط. اعمل على دفعات إذا لزم الأمر لمنع تحوّل القرنبيط إلى هريس. أنت تريد هنا قوامًا غنيًا لطيفًا. هل تريد شوربة ناعمة بدلًا من ذلك؟ لا داعي لمحضّر الطعام، فقط قطّع كل شيء تقطيعًا خشنًا. اطهِ حسب التعليمات، ثم استخدم الخلاط اليدوي لهرس الشوربة قبل إضافة صلصة الجبن النباتية. يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام، فقط احفظه في وعاء محكم الإغلاق ثم أعد تسخينه واستمتع به."],
{"Vegan Cheese Sauce":"صلصة الجبن النباتية"})
R(9354381,"صلصة معكرونة التوفو السريعة والسهلة",
"صلصة معكرونة توفو كريمية ولذيذة بنكهة الليمون مع السبانخ الطازجة والطماطم، وتكون جاهزة في 20 دقيقة!",
"4 حصص","حصة واحدة",
["12 أونصة توفو حريري، يُفضَّل أن يكون خاليًا من المحاصيل المعدلة وراثيًا إن أمكن","½ كوب مرق خضار","2 ملعقة كبيرة خميرة غذائية","2 ملعقة كبيرة عصير ليمون، أي حوالي نصف ليمونة","2 فص ثوم مقشّر","⅛ ملعقة صغيرة زعتر مجفف","¼ ملعقة صغيرة فلفل أسود أو حسب الرغبة","⅛ ملعقة صغيرة ملح البحر أو حسب الرغبة","3 حفنات كبيرة من السبانخ الصغيرة (بيبي)","10 أونصات طماطم كرزية مقطعة إلى نصفين إن أردت","½ رطل معكرونة روتيني أو من اختيارك","جبن بارميزان نباتي","فلاكس الفلفل الأحمر","ريحان طازج أو بقدونس"],
["اغلِ قدرًا كبيرًا من الماء المملح بسخاء واسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها وضعها جانبًا.","في هذه الأثناء، ضع التوفو والمرق والخميرة الغذائية وعصير الليمون والثوم والزعتر والملح والفلفل في الخلاط واخلطها حتى تصبح ناعمة.","انقل الصلصة إلى مقلاة كبيرة وأضف السبانخ والطماطم. سخّنها على نار متوسطة حتى تذبل السبانخ. ثم أضف المعكرونة المطبوخة وقلّب جيدًا وقدّم."],
["ملّح ماء المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اسلق المعكرونة حتى تصل إلى درجة \"الدنتي\". تكون المعكرونة \"الدنتي\" عادةً غير مكتملة النضج بمقدار 1-3 دقائق. هكذا يتناول الإيطاليون معكرونتهم. 😉 نحن نحب قوامًا متماسكًا قليلًا وليس رخوًا.","يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام. ستتكاثف الصلصة عندما تبرد، لذا أعد تسخينها على الموقد مع رشة من المرق لتخفيفها حتى تسخن."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9354957,"معكرونة الكوسا بالبيستو [زودلز]",
"معكرونة الكوسا بالبيستو هذه مفيدة ولذيذة وجاهزة في وقت قصير!",
"4 حصص","حصة واحدة",
["4 حبات كوسا كبيرة رفيعة وطويلة","1 ملعقة صغيرة ملح البحر","½ كوب بيستو منزلي أو من المتجر","½ ملعقة صغيرة فلاكس الفلفل الأحمر، اختياري","1 كوب طماطم عنبية مقطعة إلى نصفين","مزيد من فلاكس الفلفل الأحمر","ثوم معمر (شيف) طازج أو بقدونس أو ريحان","جبن بارميزان نباتي"],
["حوّل الكوسا إلى شرائح حلزونية وضعها في مصفاة كبيرة في حوض المطبخ أو في وعاء كبير. رشّها بالملح لإخراج الرطوبة الزائدة. اتركها جانبًا لمدة 20 دقيقة على الأقل. ستلاحظ أن الكوسا يقل حجمها مما يمنع أن تكون المعكرونة مائية لاحقًا.","سخّن البيستو على نار متوسطة إلى عالية في مقلاة كبيرة، ثم أضف الكوسا المقطعة حلزونيًا وفلاكس الفلفل الأحمر إن استخدمته. قلّب المعكرونة لمدة 2-4 دقائق حتى تسخن، ولكن لا تُفرط في الطهي.","أطفئ النار وأضف الطماطم وقلّب وقدّم مع مزيد من فلاكس الفلفل الأحمر أو الأعشاب الطازجة أو جبن البارميزان إن رغبت."],
["لتسهيل التقطيع الحلزوني، استخدم كوسا رفيعة وطويلة ومستقيمة. أو يمكنك شراء معكرونة الكوسا المقطعة حلزونيًا مسبقًا من متجر البقالة لتوفير الوقت. لا تتخطَّ التمليح! هذه الخطوة مهمة لمنع أن تصبح المعكرونة مائية بعد الطهي. فأنت تريد أن يقل حجم الكوسا لإزالة الرطوبة الزائدة. لا تُفرط في طهي المعكرونة. فأنت تريدها طرية لكن متماسكة، وليست طرية جدًا، للحصول على أفضل قوام ولتحاكي معكرونة \"الدنتي\". لتقليل الحرارة، قلّل فلاكس الفلفل الأحمر إلى النصف، أو عدّله حسب ذوقك. يمكنك تقطيع المعكرونة حلزونيًا قبل التمليح والطهي بما يصل إلى 3 أيام وحفظها في وعاء محكم الإغلاق أو كيس بسحّاب في الثلاجة. بعد الطهي، يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق. أعد تسخينه على الموقد، ولكن احرص على ألا تفرط في طهيه."],
{"For Garnish (Optional)":"للتزيين (اختياري)"})
R(9357019,"معكرونة كاجون النباتية",
"معكرونة الكاجون النباتية الحارة وجبة رائعة لأيام الأسبوع، مليئة بالنكهة والخضار الطازجة والحمص.",
"4 حصص","حصة واحدة",
["½ رطل معكرونة بيني","1 حبة بصل أصفر مفرومة ناعمًا","2 حبة فلفل رومي من أي لون","8 أونصات فطر مقطع إلى نصفين أو أرباع","1½ كوب حمص مطبوخ أو معلب (حوالي علبة 15 أونصة)","½ كوب صلصة طماطم","1 كوب مرق خضار، اختر نوعًا مالحًا/غنيًا بالنكهة","1 كوب حليب الصويا أو أي حليب آخر خالٍ من الألبان","3 ملاعق كبيرة بهارات كاجون","2 ملعقة كبيرة نشا الذرة أو أروروت أو تابيوكا","كزبرة خضراء طازجة أو بقدونس"],
["احرص على تجهيز جميع المكونات وتقطيع الخضار قبل أن تبدأ، لأن هذا الطبق يُحضَّر بسرعة كبيرة.","اسلق المعكرونة (البيني) في قدر من الماء المملح بسخاء، حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". صفّها وضعها جانبًا.","في هذه الأثناء، اخلط مكونات الصلصة في وعاء صغير أو كوب قياس وضعها جانبًا.","ثم ضع البصل المفروم والفطر والفلفل في مقلاة مع ¼ كوب من الماء. قلّبها على نار متوسطة لمدة 4-5 دقائق مع التحريك المستمر حتى تلين الخضار، لكن لا تُفرط في طهيها. ثم أضف الحمص والصلصة التي خلطتها في الخطوة السابقة إلى المقلاة نفسها. قلّب جيدًا واتركها تغلي على نار هادئة لمدة 3-4 دقائق لتتكاثف الصلصة قليلًا. (تذوّق الصلصة وأضف مزيدًا من بهارات كاجون إذا لزم الأمر، أو بعض الملح + الفلفل.)","الآن أطفئ النار وأضف المعكرونة المطبوخة إلى المقلاة نفسها وقلّب لتتغطى كل قطعة بالتساوي. قدّمها مع البقدونس أو الكزبرة الخضراء الطازجة واستمتع بها."],
["ملّح ماء المعكرونة. احرص على إضافة كمية كافية من الملح إلى قدر الماء للحصول على أفضل قوام ونكهة. إليك دليلًا مفيدًا لمساعدتك على تمليح الماء بشكل مثالي في كل مرة.","اسلق المعكرونة حتى تصل إلى درجة \"الدنتي\". لا تُفرط في سلقها! تعني \"الدنتي\" أن المعكرونة لا تزال متماسكة بعد الطهي، مما يعطي قوامًا مثاليًا في كل لقمة. لتتأكد من أن المعكرونة لا تفرط في النضج، ابدأ بتذوقها قبل بضع دقائق من الوقت المذكور على العبوة. يجب أن تكون طرية لكنها لا تزال متماسكة.","تذوّق الصلصة بعد الطهي وأضف مزيدًا من بهارات كاجون إذا كنت تفضل صلصة أكثر حرارة، أو أضف بعض الملح والفلفل الأسود عند الحاجة. (سيختلف ذلك بحسب المرق الذي استخدمته.)","حضّرت خلطة بهارات كاجون هذه لهذا الطبق. تختلف النتائج ومستويات الحرارة بحسب الوصفة أو العلامة التجارية الجاهزة المستخدمة. تذوّق الخلطة للتأكد من أن مستوى الحرارة يناسب ذوقك.","احفظ المتبقي في الثلاجة لمدة 3-4 أيام."],
{"For the vegan Cajun pasta":"للمعكرونة النباتية بنكهة كاجون","For the vegan Cajun pasta sauce":"لصلصة المعكرونة النباتية بنكهة كاجون","For garnish (optional)":"للتزيين (اختياري)"})
R(9357101,"معكرونة بالجبن النباتية في Instant Pot",
"معكرونة بالجبن نباتية بسيطة وكريمية ولذيذة في Instant Pot ستحبها أنت والأطفال الصعبو الإرضاء! إنها بنكهة الجبن وسهلة وتجهز في وقت قصير جدًا!",
"6 حصص","حصة واحدة",
["1 كوب كاجو نيء*","5½ أكواب ماء مقسّمة","¼ كوب خميرة غذائية","2 ملعقة كبيرة خل التفاح","2 ملعقة صغيرة ملح البحر","1 ملعقة صغيرة مسحوق البصل","½ ملعقة صغيرة بابريكا مدخنة","1 رطل (16 أونصة) معكرونة مكرونة (ماكاروني)"],
["ضع جميع المكونات (ما عدا المعكرونة، واستخدم كوبين فقط من الماء) في خلاط عالي السرعة واخلطها حتى تصبح ناعمة وكريمية. انقلها إلى Instant Pot وأضف الـ 3½ أكواب المتبقية من الماء وقلّب. ثم ضع المعكرونة فوقها وادفعها برفق إلى داخل الصلصة.","أغلق الغطاء وتأكد من ضبط الصمام على وضع الإغلاق. ثم اطهِ على ضغط عالٍ لمدة 4 دقائق (سيستغرق الوصول إلى الضغط حوالي 10 دقائق) وأطلق الضغط بسرعة فور انتهاء المؤقت. افتح الغطاء عندما يكون ذلك آمنًا، وقلّب كل شيء جيدًا وقدّم.","اغلِ قدرًا كبيرًا من الماء واسلق المعكرونة حسب تعليمات العبوة. ثم صفّها وأعدها إلى القدر.","في هذه الأثناء، ضع مكونات صلصة الجبن (باستخدام كوبين فقط من الماء) في الخلاط واخلطها حتى تصبح ناعمة. اسكب الصلصة فوق المعكرونة المصفّاة وقلّب جيدًا وقدّم."],
["* إذا لم يكن لديك خلاط عالي السرعة مثل فيتامكس أو بلندتك، فانقع الكاجو في ماء شديد السخونة لمدة 30 دقيقة على الأقل. ثم صفّه واستخدمه حسب التعليمات. سيساعد ذلك على تليين الكاجو مما يسهّل خلطه إلى صلصة جبن نباتية ناعمة. لاحظ أن المعكرونة بالجبن قد تبدو مائية قليلًا عند رفع الغطاء. لكن بعد بضع تقليبات ستمتص الصلصة الزائدة بسرعة. وإذا أردت زيادة العناصر الغذائية هنا، فأضف 2 كوب من البازلاء المجمدة أو الخضار المجمدة المشكلة إلى القدر قبل الطهي بالضغط. يبقى المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام. لكن المعكرونة ستواصل امتصاص الصلصة عندما تبرد، لذا عند إعادة التسخين، أضف بعض الحليب النباتي أو المرق إلى المقلاة لتخفيفها وإعادتها إلى قوام كريمي."],
{"Instant Pot Directions":"طريقة التحضير في Instant Pot","Stove Top Directions":"طريقة التحضير على الموقد"})
R(9360305,"بودينغ الشيا الليلي - بالإضافة إلى 10 نكهات!",
"بودينغ الشيا الليلي سهل التحضير ومليء بالعناصر الغذائية ويستغرق 5 دقائق من العمل اليدوي، وهو وجبة فطور أو وجبة خفيفة مثالية للتحضير المسبق.",
"حصتان","حصة واحدة",
["1 كوب حليب الكاجو أو حليب اللوز غير المحلى","3½ ملاعق كبيرة بذور الشيا","1 ملعقة كبيرة شراب القيقب أو دبس التمر، اختياري"],
["ضع المكونات الأساسية الثلاثة في وعاء محكم الإغلاق أو برطمان زجاجي واخلطها جيدًا أو رجّه بقوة. ضعه في الثلاجة طوال الليل أو لمدة 6 ساعات.","استمتع به مع الفاكهة الطازجة أو المكسرات المفرومة أو جوز الهند المبشور أو الجرانولا."],
["لا تتردد في مضاعفة الوصفة مرتين أو ثلاث أو أربع مرات حسب الحاجة. أحب تحضير دفعة كبيرة وتقسيمها إلى أوعية أو برطمانات صغيرة لتكون لديّ وجبات فطور أو وجبات خفيفة جاهزة لعدة أيام. للحصول على أفضل النتائج، أعد تحريك البودينغ أو رجّه بعد 10-15 دقيقة من وضعه في الثلاجة لتفتيت أي كتل من البذور والحصول على أفضل قوام. إذا لم يكن البودينغ سميكًا بالقدر الذي تريده، فأضف مزيدًا من بذور الشيا واتركه في الثلاجة وقتًا أطول قليلًا. إذا لم يعجبك قوام بودينغ الشيا، فيمكنك خلطه في خلاط عالي السرعة ليعطيك قوام بودينغ تقليدي أكثر، بدلًا من قوام شبيه بالتابيوكا. تبقى وصفة بودينغ الشيا الأساسية صالحة في الثلاجة لمدة 4-5 أيام. اطلع على جميع خيارات النكهات العشر في المنشور أعلاه!"])
R(9360404,"شوربة البروكلي الخالية من الألبان [سهلة جدًا!]",
"شوربة البروكلي الخالية من الألبان هذه مرضية جدًا وغنية وكريمية، وكل ذلك بدون كريمة! مكون سري يمنح هذه الشوربة قوامها الكريمي. جاهزة في 20 دقيقة فقط!",
"6 حصص","حصة واحدة",
["1 ملعقة كبيرة زبدة نباتية أو سمن نباتي (مارجرين) أو زيت طهي من اختيارك، احذفه واستبدله بالماء أو المرق إذا كنت تتجنب الزيت","1 حبة بصل أصفر مفرومة","3 فصوص ثوم مفرومة","12 كوب زهيرات بروكلي، أي حوالي رأسين كبيرين من البروكلي","6 أكواب مرق خضار قليل الصوديوم","1 حبة أفوكادو مقشّرة ومنزوعة النواة","ملح وفلفل حسب الرغبة","أفوكادو مقطع شرائح","فلفل حار أو صلصة حارة","بسكويت مالح أو خبز محمص مكعبات أو خبز مقرمش","بصل أخضر أو ثوم معمر (شيف) أو أعشاب طازجة من اختيارك"],
["في قدر كبير، ذوّب الزبدة إن استخدمتها ثم أضف البصل والثوم. قلّب حتى يلين، حوالي 5 دقائق.","ثم أضف البروكلي والمرق وأوصله إلى الغليان على نار عالية. اخفض الحرارة إلى متوسطة/منخفضة واطهِ والغطاء عليه لمدة 5-7 دقائق تقريبًا حتى يلين البروكلي عند غرزه بالشوكة.","ارفع القدر عن النار وأضف الأفوكادو إلى القدر. ثم استخدم الخلاط اليدوي لهرس الشوربة حتى تصبح ناعمة. تذوّق وأضف مزيدًا من الملح والفلفل عند الحاجة. ثم قدّم."],
["لوصفة خالية من الزيت، ببساطة احذف الزبدة النباتية واستبدلها ببعض الماء أو المرق. ورغم أنني أرى أن هذا الطبق يحتوي على كمية صحية من الدهون، فإذا كنت تتبع نظامًا غذائيًا صارمًا منخفض الدهون، فيمكنك استبدال الأفوكادو بكوب من الفاصولياء البيضاء المطبوخة أو المعلبة. وإذا لم يكن لديك خلاط يدوي، فانقل الشوربة بحذر إلى خلاط عادي. لا تملأه أكثر من اللازم، واعمل على دفعات وتوخَّ الحذر الشديد عند خلط السوائل الساخنة. يبقى المتبقي صالحًا في الثلاجة 3-4 أيام أو يُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Optional Garnishes":"للتزيين (اختياري)"})
